def _old(n):
    p = Path(__file__).resolve().parents[1] / "rn_work" / "c10_maths" / f"c{n:02d}.py"
    s = importlib.util.spec_from_file_location(f"old{n}", p); m = importlib.util.module_from_spec(s); s.loader.exec_module(m)
    return m.CH

r3 = 1.73
assert isclose(20 * r3, 34.6) and isclose(6 * r3, 10.38) and isclose(5 * r3, 8.65) and isclose(10 * r3, 17.3)
assert isclose(8 * r3 + 16, 29.84) and isclose(75 * r3, 129.75) and isclose(10 * r3 + 1.5, 18.8)
assert isclose(8 * r3, 13.84) and isclose(4 * r3, 6.92) and isclose(40 * (r3 - 1), 29.2) and isclose(40 * r3, 69.2)
assert isclose(60 * r3, 103.8) and isclose(1200 * r3, 2076) and isclose(600 * r3, 1038) and isclose(20 * (r3 - 1), 14.6)
assert isclose(3 * r3 / 2, 2.595) and isclose(20 * r3 + 0, 34.6) and isclose(10 * (r3 - 1), 7.3)
assert isclose(15 * (3 + r3), 70.95) and isclose(100 * (3 + r3) / 3, 157.666, rel_tol=1e-4) and isclose(r3 / 4, 0.4325)
assert 12 + 4 * r3 / r3 == 16 and isclose(30 * r3, 51.9) and isclose(20 * r3 + 1.6, 36.2, rel_tol=1e-3)
assert isclose(60 - 20 * r3, 25.4) and 15 + (8**2 + 15**2) ** .5 == 32 and isclose(0.8 * (r3 + 1), 2.184)
assert 4 * 14 / 3 - 3 * 14 / 4 != 0 and abs(24 * 4 / 3 - 24 * 3 / 4 - 14) < 1e-9
assert abs(1500 * r3 / r3 * 3 - 4500) < 1e-9 and (4500 - 1500) / 15 == 200 and 200 * 3.6 == 720

